export function checkUnitAnswer(id,choice){const q=unitQuestions[id];if(!q||!q.options.some(([key])=>key===choice))throw new Error('Respuesta de unidad desconocida');return {correct:q.answer===choice,feedback:q.feedback[choice]};}
export function validUnitPage(id){return unitPages.some(([key])=>id===key);}
